//! 📝️ Bounded AP214 wireframe and annotation primitives over the canonical Part21 graph.
use semio_s_artifact_stdio_contract::part21::{Part21Instance,Part21Value};
#[cfg(test)]
use semio_s_artifact_stdio_contract::part21::{Part21Document,Part21Header};
#[derive(Debug)]
pub struct DraughtingWriter{next_id:u64,context:u64,normal:u64,font:u64,curve_font:u64,curve_width:f64}
fn text(value:&str)->Part21Value{Part21Value::Str(value.into())}
fn number(value:f64)->Part21Value{Part21Value::Real(value.into())}
fn list(ids:&[u64])->Part21Value{Part21Value::List(ids.iter().copied().map(Part21Value::Ref).collect())}
fn point(value:[f64;3])->Part21Value{Part21Value::List(value.into_iter().map(number).collect())}
fn valid_point(point:[f64;3])->bool{point.into_iter().all(f64::is_finite)}
impl DraughtingWriter{
    fn alloc(&mut self,out:&mut Vec<Part21Instance>,kind:&str,args:Vec<Part21Value>)->u64{let id=self.next_id;self.next_id+=1;out.push(Part21Instance{id,entities:vec![(kind.into(),args)]});id}
    fn complex(&mut self,out:&mut Vec<Part21Instance>,entities:Vec<(&str,Vec<Part21Value>)>)->u64{let id=self.next_id;self.next_id+=1;out.push(Part21Instance{id,entities:entities.into_iter().map(|(name,args)|(name.into(),args)).collect()});id}
    fn color(&mut self,out:&mut Vec<Part21Instance>,color:[f64;3])->Result<u64,String>{if color.into_iter().any(|value|!value.is_finite()||!(0.0..=1.0).contains(&value)){return Err("step.draughting.color".into());}Ok(self.alloc(out,"COLOUR_RGB",vec![text(""),number(color[0]),number(color[1]),number(color[2])]))}
    fn assignment(&mut self,out:&mut Vec<Part21Instance>,style:u64)->u64{self.alloc(out,"PRESENTATION_STYLE_ASSIGNMENT",vec![list(&[style])])}
    fn model(&mut self,out:&mut Vec<Part21Instance>,name:&str,item:u64){self.alloc(out,"DRAUGHTING_MODEL",vec![text(name),list(&[item]),Part21Value::Ref(self.context)]);}
    fn wireframe(&mut self,out:&mut Vec<Part21Instance>,name:&str,curve:u64,stroke:Option<[f64;3]>)->Result<(),String>{let set=self.alloc(out,"GEOMETRIC_CURVE_SET",vec![text(name),list(&[curve])]);self.alloc(out,"GEOMETRICALLY_BOUNDED_WIREFRAME_SHAPE_REPRESENTATION",vec![text(name),list(&[set]),Part21Value::Ref(self.context)]);if let Some(color)=stroke{let color=self.color(out,color)?;let style=self.alloc(out,"CURVE_STYLE",vec![text(name),Part21Value::Ref(self.curve_font),Part21Value::Typed{name:"POSITIVE_LENGTH_MEASURE".into(),items:vec![number(self.curve_width)]},Part21Value::Ref(color)]);let assignment=self.assignment(out,style);let styled=self.alloc(out,"STYLED_ITEM",vec![text(name),list(&[assignment]),Part21Value::Ref(curve)]);self.model(out,&format!("{name}/stroke"),styled);}Ok(())}
    /// 🧭️ Initializes explicit SI millimetre/radian/steradian context and standard draughting fonts.
    pub fn new(first_id:u64)->Result<(Self,Vec<Part21Instance>),String>{if first_id==0||first_id>u64::MAX/2{return Err("step.draughting.id".into());}let mut writer=Self{next_id:first_id,context:0,normal:0,font:0,curve_font:0,curve_width:0.5*25.4/72.0};let mut out=Vec::new();let length=writer.complex(&mut out,vec![("LENGTH_UNIT",Vec::new()),("NAMED_UNIT",vec![Part21Value::Derived]),("SI_UNIT",vec![Part21Value::Enum("MILLI".into()),Part21Value::Enum("METRE".into())])]);let angle=writer.complex(&mut out,vec![("NAMED_UNIT",vec![Part21Value::Derived]),("PLANE_ANGLE_UNIT",Vec::new()),("SI_UNIT",vec![Part21Value::Unset,Part21Value::Enum("RADIAN".into())])]);let solid=writer.complex(&mut out,vec![("NAMED_UNIT",vec![Part21Value::Derived]),("SI_UNIT",vec![Part21Value::Unset,Part21Value::Enum("STERADIAN".into())]),("SOLID_ANGLE_UNIT",Vec::new())]);writer.context=writer.complex(&mut out,vec![("GEOMETRIC_REPRESENTATION_CONTEXT",vec![Part21Value::Int(3)]),("GLOBAL_UNIT_ASSIGNED_CONTEXT",vec![list(&[length,angle,solid])]),("REPRESENTATION_CONTEXT",vec![text("Layout"),text("3D")])]);writer.normal=writer.alloc(&mut out,"DIRECTION",vec![text(""),point([0.0,0.0,1.0])]);writer.font=writer.alloc(&mut out,"DRAUGHTING_PRE_DEFINED_TEXT_FONT",vec![text("ISO 3098")]);writer.curve_font=writer.alloc(&mut out,"DRAUGHTING_PRE_DEFINED_CURVE_FONT",vec![text("continuous")]);Ok((writer,out))}
    /// 🖋️ Chooses the next positive physical pen width without retaining a style object.
    pub fn set_curve_width(&mut self,width:f64)->Result<(),String>{if !width.is_finite()||width<=0.0{return Err("step.draughting.curve-width".into());}self.curve_width=width;Ok(())}
    /// 🧱️ Connects the page solid to the same explicit physical representation context.
    pub fn solid_representation(&mut self,name:&str,solid:u64)->Vec<Part21Instance>{let mut out=Vec::new();self.alloc(&mut out,"ADVANCED_BREP_SHAPE_REPRESENTATION",vec![text(name),list(&[solid]),Part21Value::Ref(self.context)]);out}
    /// 📐️ Emits bounded wireframe geometry and optional fill annotation without retaining file bodies.
    pub fn path(&mut self,name:&str,points:&[[f64;3]],stroke:Option<[f64;3]>,fill:Option<[f64;3]>)->Result<Vec<Part21Instance>,String>{if name.len()>512||points.len()<2||points.len()>65||points.iter().copied().any(|point|!valid_point(point)){return Err("step.draughting.path".into());}let closed=points.first()==points.last();if fill.is_some()&&!closed{return Err("step.draughting.open-fill".into());}let mut out=Vec::new();let mut ids=Vec::new();for(index,value)in points.iter().enumerate(){if index+1==points.len()&&closed{ids.push(ids[0]);}else{ids.push(self.alloc(&mut out,"CARTESIAN_POINT",vec![text(""),point(*value)]));}if points.len()==2&&index==0{let end=points[1];let middle=[(value[0]+end[0])*0.5,(value[1]+end[1])*0.5,(value[2]+end[2])*0.5];ids.push(self.alloc(&mut out,"CARTESIAN_POINT",vec![text(""),point(middle)]));}}let curve=self.alloc(&mut out,"POLYLINE",vec![text(name),list(&ids)]);self.wireframe(&mut out,name,curve,stroke)?;if let Some(color)=fill{let color=self.color(&mut out,color)?;let color_style=self.alloc(&mut out,"FILL_AREA_STYLE_COLOUR",vec![text(name),Part21Value::Ref(color)]);let style=self.alloc(&mut out,"FILL_AREA_STYLE",vec![text(name),list(&[color_style])]);let assignment=self.assignment(&mut out,style);let area=self.alloc(&mut out,"ANNOTATION_FILL_AREA",vec![text(name),list(&[curve])]);let occurrence=self.alloc(&mut out,"ANNOTATION_FILL_AREA_OCCURRENCE",vec![text(name),list(&[assignment]),Part21Value::Ref(area),Part21Value::Ref(ids[0])]);self.model(&mut out,&format!("{name}/fill"),occurrence);}Ok(out)}
    /// ⭕️ Emits an exact XY circle using a true CIRCLE and AXIS2_PLACEMENT_3D.
    pub fn circle(&mut self,name:&str,center:[f64;3],radius:f64,stroke:Option<[f64;3]>)->Result<Vec<Part21Instance>,String>{if name.len()>512||!valid_point(center)||!radius.is_finite()||radius<=0.0{return Err("step.draughting.circle".into());}let mut out=Vec::new();let center=self.alloc(&mut out,"CARTESIAN_POINT",vec![text(""),point(center)]);let axis=self.alloc(&mut out,"AXIS2_PLACEMENT_3D",vec![text(""),Part21Value::Ref(center),Part21Value::Ref(self.normal),Part21Value::Unset]);let circle=self.alloc(&mut out,"CIRCLE",vec![text(name),Part21Value::Ref(axis),number(radius)]);self.wireframe(&mut out,name,circle,stroke)?;Ok(out)}
    /// 🔤️ Emits Unicode text, explicit extent, ISO draughting font, character height and annotation occurrence.
    pub fn text(&mut self,name:&str,literal:&str,position:[f64;3],rotation:f64,width:f64,height:f64,font_size:f64,color:Option<[f64;3]>)->Result<Vec<Part21Instance>,String>{if name.len()>512||literal.len()>512||!valid_point(position)||[rotation,width,height,font_size].iter().any(|value|!value.is_finite())||width<=0.0||height<=0.0||font_size<=0.0{return Err("step.draughting.text".into());}let mut out=Vec::new();let origin=self.alloc(&mut out,"CARTESIAN_POINT",vec![text(""),point(position)]);let(sin,cos)=rotation.sin_cos();let direction=self.alloc(&mut out,"DIRECTION",vec![text(""),point([cos,sin,0.0])]);let axis=self.alloc(&mut out,"AXIS2_PLACEMENT_3D",vec![text(""),Part21Value::Ref(origin),Part21Value::Ref(self.normal),Part21Value::Ref(direction)]);let extent=self.alloc(&mut out,"PLANAR_EXTENT",vec![text(name),number(width),number(height)]);let item=self.alloc(&mut out,"TEXT_LITERAL_WITH_EXTENT",vec![text(name),text(literal),Part21Value::Ref(axis),text("bottom left"),Part21Value::Enum("RIGHT".into()),Part21Value::Ref(self.font),Part21Value::Ref(extent)]);let color=self.color(&mut out,color.unwrap_or([0.0,0.0,0.0]))?;let appearance=self.alloc(&mut out,"TEXT_STYLE_FOR_DEFINED_FONT",vec![Part21Value::Ref(color)]);let style=self.alloc(&mut out,"TEXT_STYLE_WITH_BOX_CHARACTERISTICS",vec![text(name),Part21Value::Ref(appearance),Part21Value::List(vec![Part21Value::Typed{name:"BOX_HEIGHT".into(),items:vec![number(font_size)]}])]);let assignment=self.assignment(&mut out,style);let occurrence=self.alloc(&mut out,"ANNOTATION_TEXT_OCCURRENCE",vec![text(name),list(&[assignment]),Part21Value::Ref(item)]);self.model(&mut out,&format!("{name}/text"),occurrence);Ok(out)}
}
